import{_ as t,o as i,c as r,a2 as a}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Tableau Chronologique Synthétique","description":"","frontmatter":{},"headers":[],"relativePath":"fr/0093-编年史简表.md","filePath":"fr/0093-编年史简表.md"}'),n={name:"fr/0093-编年史简表.md"};function s(d,e,l,o,u,c){return i(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="tableau-chronologique-synthetique" tabindex="-1">Tableau Chronologique Synthétique <a class="header-anchor" href="#tableau-chronologique-synthetique" aria-label="Permalink to &quot;Tableau Chronologique Synthétique&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>93</td></tr><tr><td>Module</td><td>Annexes et matériaux de référence</td></tr><tr><td>Mots-clés principaux</td><td>chronologie, division des ères, événements majeurs, jalons historiques, Univers Hengyuan</td></tr></tbody></table><h2 id="i-notes-sur-la-chronologie" tabindex="-1">I. Notes sur la chronologie <a class="header-anchor" href="#i-notes-sur-la-chronologie" aria-label="Permalink to &quot;I. Notes sur la chronologie&quot;">​</a></h2><p>Ce tableau enregistre, sur la base du temps standard de l&#39;Univers Hengyuan, les événements historiques majeurs et les jalons clés du développement de la Civilisation Symbiotique de l&#39;Ancre, classés dans l&#39;ordre des ères. La période couverte s&#39;étend de l&#39;époque antique de l&#39;ère pré-Ancre aux perspectives futures de l&#39;ère de la symbiose interstellaire. Chaque ère indique son début et sa fin, ses caractéristiques et ses événements majeurs. Ce tableau est un index historique hautement condensé ; pour l&#39;histoire détaillée de chaque ère, voir les comptes rendus dédiés dans les documents 70-79.</p><h2 id="ii-apercu-general-de-la-division-des-eres" tabindex="-1">II. Aperçu général de la division des ères <a class="header-anchor" href="#ii-apercu-general-de-la-division-des-eres" aria-label="Permalink to &quot;II. Aperçu général de la division des ères&quot;">​</a></h2><table tabindex="0"><thead><tr><th>N° d&#39;ère</th><th>Nom de l&#39;ère</th><th>Période (années standard de l&#39;Univers Hengyuan)</th><th>Durée</th><th>Caractéristiques principales</th></tr></thead><tbody><tr><td>Première ère</td><td>Ère pré-Ancre</td><td>environ -10 milliards à -10 000 ans</td><td>environ 10 milliards d&#39;années</td><td>Les systèmes de culture prédatrice dominaient ; les civilisations s&#39;élevaient et déclinaient en cycles</td></tr><tr><td>Deuxième ère</td><td>Ère de l&#39;Éveil de l&#39;Ancre</td><td>-10 000 à -1 000 ans</td><td>environ 9 000 ans</td><td>Le mécanisme de l&#39;Ancre fut découvert et initialement appliqué</td></tr><tr><td>Troisième ère</td><td>Période d&#39;établissement du système symbiotique</td><td>-1 000 à -100 ans</td><td>environ 900 ans</td><td>Le cadre institutionnel de la Civilisation Symbiotique de l&#39;Ancre se mit progressivement en place</td></tr><tr><td>Quatrième ère</td><td>Période d&#39;ouverture des Trois Cents Systèmes</td><td>-100 à -50 ans</td><td>environ 50 ans</td><td>Les Trois Cents Systèmes de Culture d&#39;Origine furent entièrement ouverts</td></tr><tr><td>Cinquième ère</td><td>Période de la Stratégie d&#39;activation de 20 %</td><td>-50 ans à l&#39;an un</td><td>environ 50 ans</td><td>20 % des êtres vivants furent activés en Puissances Suprêmes du Plan</td></tr><tr><td>Sixième ère</td><td>Ère de la première élévation</td><td>l&#39;an un à 100</td><td>100 ans</td><td>La civilisation symbiotique réalisa sa première élévation par étapes</td></tr><tr><td>Septième ère</td><td>Ère de la République des Dix Mille Races</td><td>100 à 500</td><td>400 ans</td><td>La République des Dix Mille Races fut officiellement établie ; l&#39;intégration interraciale s&#39;approfondit</td></tr><tr><td>Huitième ère</td><td>Ère de l&#39;exploration transplanaire</td><td>500 à 2000</td><td>1 500 ans</td><td>De vastes activités d&#39;exploration et d&#39;archéologie transplanaires furent déployées</td></tr><tr><td>Neuvième ère</td><td>Ère de la symbiose interstellaire</td><td>2000 à l&#39;avenir</td><td>en cours</td><td>Un réseau de symbiose à l&#39;échelle de l&#39;univers fut achevé ; l&#39;élévation globale progressa</td></tr></tbody></table><p>Note : « l&#39;an un » désigne l&#39;année de la proclamation officielle de la Civilisation Symbiotique de l&#39;Ancre, servant de point de repère de ce calendrier historique.</p><h2 id="iii-l-ere-pre-ancre-environ-10-milliards-a-10-000-ans" tabindex="-1">III. L&#39;ère pré-Ancre (environ -10 milliards à -10 000 ans) <a class="header-anchor" href="#iii-l-ere-pre-ancre-environ-10-milliards-a-10-000-ans" aria-label="Permalink to &quot;III. L&#39;ère pré-Ancre (environ -10 milliards à -10 000 ans)&quot;">​</a></h2><p>L&#39;ère pré-Ancre fut l&#39;ère la plus longue de l&#39;histoire de l&#39;Univers Hengyuan, durant environ dix milliards d&#39;années. Sa caractéristique fondamentale était la domination des systèmes de culture prédatrice sur l&#39;univers, les civilisations s&#39;engageant sans cesse dans le cycle « essor — apogée — prédation — effondrement ».</p><table tabindex="0"><thead><tr><th>Repère temporel</th><th>Événement majeur</th></tr></thead><tbody><tr><td>environ -10 milliards d&#39;années</td><td>Le réseau de lois de l&#39;Univers Hengyuan se stabilisa ; les premiers plans matériels se formèrent ; l&#39;univers entra dans un état habitable</td></tr><tr><td>environ -8 milliards d&#39;années</td><td>Les premières vies intelligentes émergèrent sur de multiples plans matériels ; les systèmes de culture primitifs commencèrent à germer</td></tr><tr><td>environ -5 milliards d&#39;années</td><td>Les systèmes de culture prédatrice devinrent progressivement dominants ; les forts réalisèrent une évolution rapide en dévorant les faibles</td></tr><tr><td>environ -3 milliards d&#39;années</td><td>La première guerre de prédation à l&#39;échelle de l&#39;univers éclata ; les civilisations de plusieurs régions stellaires subirent des coups dévastateurs</td></tr><tr><td>environ -1 milliard d&#39;années</td><td>Les défauts du système prédateur commencèrent à se manifester ; l&#39;augmentation globale de l&#39;entropie de l&#39;univers s&#39;accéléra ; les ressources de culture s&#39;épuisèrent progressivement</td></tr><tr><td>environ -500 millions d&#39;années</td><td>Les premiers penseurs réfléchissant au système prédateur apparurent ; les germes de la pensée symbiotique commencèrent à se former</td></tr><tr><td>environ -100 millions d&#39;années</td><td>De petites civilisations expérimentales symbiotiques émergèrent dans plusieurs régions stellaires, mais toutes furent détruites par les civilisations prédatrices</td></tr><tr><td>environ -1 million d&#39;années</td><td>L&#39;univers dans son ensemble entra dans la « Grande Décadence » ; tant le nombre de civilisations que le niveau de culture tombèrent à des creux historiques</td></tr><tr><td>environ -10 000 ans</td><td>Un cultivateur du Premier Plan, au cours d&#39;une longue culture, perçut accidentellement un nœud stable du réseau de lois ; le mécanisme de l&#39;Ancre fut découvert pour la première fois</td></tr></tbody></table><h2 id="iv-l-ere-de-l-eveil-de-l-ancre-10-000-a-1-000-ans" tabindex="-1">IV. L&#39;ère de l&#39;Éveil de l&#39;Ancre (-10 000 à -1 000 ans) <a class="header-anchor" href="#iv-l-ere-de-l-eveil-de-l-ancre-10-000-a-1-000-ans" aria-label="Permalink to &quot;IV. L&#39;ère de l&#39;Éveil de l&#39;Ancre (-10 000 à -1 000 ans)&quot;">​</a></h2><p>L&#39;ère de l&#39;Éveil de l&#39;Ancre fut la période de transition du mécanisme de l&#39;Ancre, de la découverte à l&#39;application initiale. Sa caractéristique principale fut la maturation progressive de la technologie de l&#39;Ancre et la diffusion de la pensée symbiotique.</p><table tabindex="0"><thead><tr><th>Repère temporel</th><th>Événement majeur</th></tr></thead><tbody><tr><td>-10 000 ans</td><td>Le mécanisme de l&#39;Ancre fut découvert pour la première fois ; son découvreur le nomma « l&#39;Ancre » et commença une recherche systématique</td></tr><tr><td>-9 000 ans</td><td>La première Ancre artificielle fut établie avec succès, prouvant que les Ancres pouvaient être construites et entretenues artificiellement</td></tr><tr><td>-8 000 ans</td><td>La technologie de l&#39;Ancre commença à se diffuser à petite échelle ; les premiers cultivateurs de l&#39;Ancre apparurent</td></tr><tr><td>-7 000 ans</td><td>Il fut découvert que les Ancres pouvaient servir de repères pour les connexions transplanaires ; la première traversée de plan assistée par l&#39;Ancre, consignée, réussit</td></tr><tr><td>-6 000 ans</td><td>La pensée symbiotique commença à se combiner à la technologie de l&#39;Ancre ; les premiers textes théoriques sur la « Symbiose de l&#39;Ancre » furent publiés</td></tr><tr><td>-5 000 ans</td><td>La première cité-État symbiotique fondée sur l&#39;Ancre fut établie, prouvant la faisabilité du système symbiotique</td></tr><tr><td>-4 000 ans</td><td>Les civilisations prédatrices attaquèrent les cités-États symbiotiques ; celles-ci se défendirent avec succès grâce à la technologie de l&#39;Ancre</td></tr><tr><td>-3 000 ans</td><td>La pensée symbiotique se diffusa dans de multiples régions stellaires ; de plus en plus de civilisations tentèrent la transition symbiotique</td></tr><tr><td>-2 000 ans</td><td>La première « Grande Assemblée de Symbiose des Dix Mille Races » se tint ; des représentants de dizaines de races débattirent ensemble de l&#39;avenir de la civilisation symbiotique</td></tr><tr><td>-1 000 ans</td><td>La technologie de l&#39;Ancre et la pensée symbiotique avaient acquis les conditions d&#39;établissement d&#39;une civilisation unifiée ; la Période d&#39;établissement du système symbiotique commença</td></tr></tbody></table><h2 id="v-la-periode-d-etablissement-du-systeme-symbiotique-1-000-a-100-ans" tabindex="-1">V. La Période d&#39;établissement du système symbiotique (-1 000 à -100 ans) <a class="header-anchor" href="#v-la-periode-d-etablissement-du-systeme-symbiotique-1-000-a-100-ans" aria-label="Permalink to &quot;V. La Période d&#39;établissement du système symbiotique (-1 000 à -100 ans)&quot;">​</a></h2><p>La Période d&#39;établissement du système symbiotique fut la période cruciale où le cadre institutionnel de la Civilisation Symbiotique de l&#39;Ancre se constitua de toutes pièces.</p><table tabindex="0"><thead><tr><th>Repère temporel</th><th>Événement majeur</th></tr></thead><tbody><tr><td>-1 000 ans</td><td>Le Comité de rédaction de la Constitution Symbiotique fut établi et commença à rédiger la loi fondamentale</td></tr><tr><td>-950 ans</td><td>Le projet de la Constitution Symbiotique fut achevé ; les avis des dix mille races furent largement sollicités</td></tr><tr><td>-900 ans</td><td>La Constitution Symbiotique fut adoptée par référendum populaire et entra en vigueur ; la Civilisation Symbiotique de l&#39;Ancre fut proclamée</td></tr><tr><td>-850 ans</td><td>Les trois grandes institutions — l&#39;Assemblée Délibérante de l&#39;Ancre, le Comité Exécutif Symbiotique et le Tribunal Symbiotique — furent officiellement établies et opérationnelles</td></tr><tr><td>-800 ans</td><td>Le Mécanisme de contrat lié à la production commença à être promu sur l&#39;ensemble du territoire</td></tr><tr><td>-700 ans</td><td>Des lois fondamentales telles que la Loi Symbiotique du Travail et la Loi sur la Protection des Consommateurs furent promulguées les unes après les autres</td></tr><tr><td>-600 ans</td><td>Les cinq lois d&#39;accompagnement sur l&#39;éducation, la santé, le logement, l&#39;environnement et la lutte contre les monopoles furent toutes promulguées et mises en œuvre</td></tr><tr><td>-500 ans</td><td>Les travaux d&#39;excavation et de compilation des Trois Cents Systèmes de Culture d&#39;Origine furent officiellement lancés</td></tr><tr><td>-400 ans</td><td>Les cinquante premiers Systèmes de Culture d&#39;Origine achevèrent leur compilation et leur vérification</td></tr><tr><td>-300 ans</td><td>Des percées furent réalisées dans l&#39;application technologique du Fruit Multiplicateur ; la technologie d&#39;amplification déductive au centuple parvint à maturité</td></tr><tr><td>-200 ans</td><td>Les Trois Cents Systèmes achevèrent tous leur compilation et entrèrent dans l&#39;étape finale de validation de sécurité</td></tr><tr><td>-100 ans</td><td>Les conditions d&#39;ouverture complète des Trois Cents Systèmes de Culture d&#39;Origine furent réunies ; la période d&#39;ouverture commença</td></tr></tbody></table><h2 id="vi-la-periode-d-ouverture-des-trois-cents-systemes-100-a-50-ans" tabindex="-1">VI. La Période d&#39;ouverture des Trois Cents Systèmes (-100 à -50 ans) <a class="header-anchor" href="#vi-la-periode-d-ouverture-des-trois-cents-systemes-100-a-50-ans" aria-label="Permalink to &quot;VI. La Période d&#39;ouverture des Trois Cents Systèmes (-100 à -50 ans)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Repère temporel</th><th>Événement majeur</th></tr></thead><tbody><tr><td>-100 ans</td><td>Les Trois Cents Systèmes de Culture d&#39;Origine furent officiellement ouverts gratuitement à tous les êtres vivants de l&#39;univers</td></tr><tr><td>-90 ans</td><td>Le nombre de cultivateurs fut multiplié par cent en dix ans ; « un chemin pour chacun » fut préliminairement réalisé</td></tr><tr><td>-80 ans</td><td>Les Trois Fondations d&#39;Origine (Itération Déductive, Cycle de Vie et régulation des principes juridiques spatiaux) devinrent les systèmes les plus populaires</td></tr><tr><td>-70 ans</td><td>Les premiers cultivateurs ayant atteint de hauts niveaux par les nouveaux systèmes apparurent, prouvant l&#39;efficacité des systèmes</td></tr><tr><td>-60 ans</td><td>Le réseau de mentors fut entièrement établi ; les cultivateurs avancés commencèrent à remplir leur devoir légal de guider les cultivateurs débutants</td></tr><tr><td>-50 ans</td><td>Le niveau de culture général de l&#39;ensemble de la population s&#39;améliora considérablement ; les conditions de la Stratégie d&#39;activation de 20 % furent réunies</td></tr></tbody></table><h2 id="vii-la-periode-de-la-strategie-d-activation-de-20-50-ans-a-l-an-un" tabindex="-1">VII. La Période de la Stratégie d&#39;activation de 20 % (-50 ans à l&#39;an un) <a class="header-anchor" href="#vii-la-periode-de-la-strategie-d-activation-de-20-50-ans-a-l-an-un" aria-label="Permalink to &quot;VII. La Période de la Stratégie d&#39;activation de 20 % (-50 ans à l&#39;an un)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Repère temporel</th><th>Événement majeur</th></tr></thead><tbody><tr><td>-50 ans</td><td>La Stratégie d&#39;activation de 20 % fut officiellement lancée, visant à activer 20 % des êtres vivants en Puissances Suprêmes du Plan en 50 ans</td></tr><tr><td>-40 ans</td><td>Les premières Puissances Suprêmes du Plan naquirent ; le taux d&#39;activation atteignit 5 %</td></tr><tr><td>-30 ans</td><td>Le taux d&#39;activation atteignit 10 % ; les Puissances Suprêmes du Plan commencèrent à jouer un rôle central dans l&#39;entretien des Ancres</td></tr><tr><td>-20 ans</td><td>Le taux d&#39;activation atteignit 15 % ; le niveau de culture général de l&#39;univers réalisa un bond qualitatif</td></tr><tr><td>-10 ans</td><td>Le taux d&#39;activation atteignit 18 %, approchant de l&#39;objectif stratégique</td></tr><tr><td>L&#39;an un</td><td>Le taux d&#39;activation atteignit 20,3 % ; la Stratégie d&#39;activation de 20 % fut menée à bien avec un plein succès, et la Civilisation Symbiotique de l&#39;Ancre entra dans une nouvelle ère</td></tr></tbody></table><h2 id="viii-l-ere-de-la-premiere-elevation-l-an-un-a-100" tabindex="-1">VIII. L&#39;Ère de la première élévation (l&#39;an un à 100) <a class="header-anchor" href="#viii-l-ere-de-la-premiere-elevation-l-an-un-a-100" aria-label="Permalink to &quot;VIII. L&#39;Ère de la première élévation (l&#39;an un à 100)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Repère temporel</th><th>Événement majeur</th></tr></thead><tbody><tr><td>L&#39;an un</td><td>La civilisation symbiotique proclama officiellement son entrée dans l&#39;ère de l&#39;élévation ; la première étape de la Voie d&#39;Élévation en Quatre Étapes (Fondation de la réalité) fut achevée</td></tr><tr><td>20</td><td>La deuxième étape (Autonomisation technologique) avança sur tous les fronts ; les lois de culture et l&#39;ingénierie technologique s&#39;intégrèrent profondément</td></tr><tr><td>40</td><td>Les technologies du Miroir de Réplication et de l&#39;espace isolé atteignirent une production de masse à l&#39;échelle industrielle ; l&#39;archéologie transplanaire entra dans l&#39;ère de l&#39;échelle</td></tr><tr><td>60</td><td>Les premiers cultivateurs d&#39;élévation de la conscience atteignirent de hauts niveaux ; la troisième étape (Évolution de la conscience) commença</td></tr><tr><td>80</td><td>La construction des infrastructures du domaine de la conscience fut achevée ; la technologie de migration de la conscience parvint préliminairement à maturité</td></tr><tr><td>100</td><td>La première élévation par étapes réussit ; la civilisation symbiotique dans son ensemble fut élevée d&#39;un demi-niveau de dimension</td></tr></tbody></table><h2 id="ix-l-ere-de-la-republique-des-dix-mille-races-100-a-500" tabindex="-1">IX. L&#39;Ère de la République des Dix Mille Races (100 à 500) <a class="header-anchor" href="#ix-l-ere-de-la-republique-des-dix-mille-races-100-a-500" aria-label="Permalink to &quot;IX. L&#39;Ère de la République des Dix Mille Races (100 à 500)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Repère temporel</th><th>Événement majeur</th></tr></thead><tbody><tr><td>100</td><td>La République des Dix Mille Races fut officiellement proclamée ; toutes les races intelligentes réalisèrent une union égale dans le cadre de la civilisation symbiotique</td></tr><tr><td>150</td><td>Le Registre des Dix Mille Races acheva sa compilation, recensant toutes les races intelligentes connues</td></tr><tr><td>200</td><td>Les mariages interraciaux et la fusion culturelle devinrent la norme ; de nouvelles races mixtes commencèrent à apparaître</td></tr><tr><td>300</td><td>La promotion d&#39;une langue commune des dix mille races fut achevée ; les obstacles à la communication interraciale furent pratiquement éliminés</td></tr><tr><td>400</td><td>Les cultures des Dix Mille Races connurent une grande prospérité ; les cultures traditionnelles de chaque race furent protégées et développées dans le cadre symbiotique</td></tr><tr><td>500</td><td>La République des Dix Mille Races entra dans sa période de maturité ; les conditions de l&#39;exploration transplanaire furent entièrement réunies</td></tr></tbody></table><h2 id="x-l-ere-de-l-exploration-transplanaire-500-a-2000" tabindex="-1">X. L&#39;Ère de l&#39;exploration transplanaire (500 à 2000) <a class="header-anchor" href="#x-l-ere-de-l-exploration-transplanaire-500-a-2000" aria-label="Permalink to &quot;X. L&#39;Ère de l&#39;exploration transplanaire (500 à 2000)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Repère temporel</th><th>Événement majeur</th></tr></thead><tbody><tr><td>500</td><td>Le programme d&#39;exploration transplanaire à grande échelle fut officiellement lancé ; l&#39;Administration des Plans fut établie</td></tr><tr><td>600</td><td>Plus d&#39;un millier de plans furent explorés ; la base maîtresse des coordonnées de plans fut préliminairement constituée</td></tr><tr><td>800</td><td>Le schéma d&#39;archéologie à distance par Miroir de Réplication parvint à pleine maturité ; l&#39;archéologie transplanaire entra dans son âge d&#39;or</td></tr><tr><td>1000</td><td>Des percées furent réalisées dans la technologie de régression temporelle ; le principe d&#39;observer d&#39;abord, puis intervenir dans les limites fut officiellement établi</td></tr><tr><td>1200</td><td>Plus de cent mille plans furent explorés ; des relations diplomatiques furent établies avec des dizaines de civilisations de plans</td></tr><tr><td>1500</td><td>Les directives éthiques transplanaires furent pleinement mises en œuvre ; les interactions entre civilisations entrèrent dans l&#39;ère de la réglementation</td></tr><tr><td>1800</td><td>Le mécanisme de prévention et de contrôle des paradoxes temporels parvint à pleine maturité ; l&#39;archéologie par régression temporelle atteignit l&#39;échelle</td></tr><tr><td>2000</td><td>L&#39;exploration transplanaire obtint des résultats éclatants ; les conditions de l&#39;Ère de la symbiose interstellaire furent entièrement réunies</td></tr></tbody></table><h2 id="xi-l-ere-de-la-symbiose-interstellaire-2000-a-l-avenir" tabindex="-1">XI. L&#39;Ère de la symbiose interstellaire (2000 à l&#39;avenir) <a class="header-anchor" href="#xi-l-ere-de-la-symbiose-interstellaire-2000-a-l-avenir" aria-label="Permalink to &quot;XI. L&#39;Ère de la symbiose interstellaire (2000 à l&#39;avenir)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Repère temporel</th><th>Événement majeur</th></tr></thead><tbody><tr><td>2000</td><td>L&#39;Ère de la symbiose interstellaire commença officiellement ; la quatrième étape (Symbiose interstellaire) avança sur tous les fronts</td></tr><tr><td>2500 (perspective)</td><td>Le réseau d&#39;Ancres à l&#39;échelle de l&#39;univers fut préliminairement achevé, couvrant tous les plans explorés</td></tr><tr><td>3000 (perspective)</td><td>Le système de symbiose transplanaire parvint à maturité ; les Dix Mille Races réalisèrent une véritable symbiose à l&#39;échelle de l&#39;univers</td></tr><tr><td>5000 (perspective)</td><td>L&#39;élévation globale de l&#39;univers fut achevée ; l&#39;Univers Hengyuan entra dans un état d&#39;existence à une dimension supérieure</td></tr><tr><td>L&#39;avenir (perspective)</td><td>La Civilisation Symbiotique de l&#39;Ancre continua d&#39;explorer au-delà de l&#39;univers, diffusant l&#39;idéal de symbiose vers des existences plus vastes</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Le tableau chronologique est l&#39;épopée de lutte de la Civilisation Symbiotique de l&#39;Ancre — de l&#39;ignorance à l&#39;éveil, de la faiblesse à la force, de son propre plan à l&#39;univers entier. La succession de chaque ère témoigne de la victoire de l&#39;idéal symbiotique sur l&#39;idéal prédateur et du progrès civilisé sur le déclin barbare. L&#39;histoire n&#39;est pas la poussière du passé, mais la semence de l&#39;avenir — comprendre cette histoire, c&#39;est comprendre d&#39;où vient la civilisation symbiotique et où elle va.</p><h2 id="documents-associes" tabindex="-1">Documents associés <a class="header-anchor" href="#documents-associes" aria-label="Permalink to &quot;Documents associés&quot;">​</a></h2><ul><li>70-纪元划分总表 (Tableau Maître de la Division des Ères)</li><li>72-锚点觉醒纪元 (L&#39;Ère de l&#39;Éveil de l&#39;Ancre)</li><li>79-星际共生时代展望 (Les Perspectives de l&#39;Ère de la Symbiose Interstellaire)</li></ul>',32)])])}const v=t(n,[["render",s]]);export{p as __pageData,v as default};
